import {playEvidence} from './play-evidence.js';
import {PLAYERS,SCENARIOS,position,events} from './engine.js';
import {matchSession} from './match-session.js';
import {matchCenterSnapshot} from './analysis-model.js';
import {createMatchPitch} from './match-pitch.js';
const el=(tag,text,cls)=>{const n=document.createElement(tag);if(text)n.textContent=text;if(cls)n.className=cls;return n;};
const dialog=el('dialog',null,'play-studio');dialog.setAttribute('aria-labelledby','play-studio-title');
const header=el('header',null,'ps-head'),heading=el('div');heading.append(el('small','BTR / INSIDE THE PLAY'));const title=el('h2','Every story. See the evidence.');title.id='play-studio-title';heading.append(title);const close=el('button','Close ×');header.append(heading,close);
const tabs=el('nav',null,'ps-tabs');tabs.setAttribute('aria-label','Evidence experiences');
const grid=el('div',null,'ps-grid'),left=el('section'),pitchBox=el('div',null,'ps-pitch'),controls=el('div',null,'ps-controls'),play=el('button','Play'),range=el('input'),clock=el('span');range.type='range';range.min=0;range.max=36;range.step=.1;range.setAttribute('aria-label','Evidence replay time');controls.append(play,range,clock);const note=el('p','Synthetic tracking replay. Lines show recorded geometry, not video tracking or proof of causation.','ps-note');left.append(pitchBox,controls,note);const copy=el('section',null,'ps-copy');copy.setAttribute('aria-live','polite');grid.append(left,copy);dialog.append(header,tabs,grid);document.body.append(dialog);
let input={},tab='why',learn='Show me',focus=7,timer=null,origin=null,history=[],quote=null,guess=null;
const pitch=createMatchPitch(pitchBox,id=>{focus=id;render();});
const modes=[['why','Show me why'],['off','Off the ball'],['fans','Two fans. One truth.'],['story','A story changes'],['learn','Learn your way'],['missing','What’s missing?']];
for(const [id,label] of modes){const b=el('button',label);b.dataset.tab=id;b.onclick=()=>{stop();tab=id;render();};tabs.append(b);}
function stop(){clearInterval(timer);timer=null;play.textContent='Play';}
function open(detail={}){stop();origin=document.activeElement;const state=matchSession.get();input={scenario:detail.scenario||state.scenario,time:detail.time??(state.source==='match'?state.time:16),corrected:detail.corrected??state.corrected,tracking:true,eventId:detail.ids?.find(id=>id.includes('-evt-'))};quote=detail.quote?detail:null;tab='why';history=[];guess=null;document.querySelectorAll('video').forEach(v=>v.pause());focus=SCENARIOS.find(s=>s.id===input.scenario)?.focus||7;render();if(!dialog.open)dialog.showModal();}
close.onclick=()=>dialog.close();dialog.addEventListener('close',()=>{stop();origin?.focus();});
range.oninput=()=>{stop();input.time=+range.value;quote=null;input.eventId=null;guess=null;history=[];render();};
play.onclick=()=>{if(timer){stop();return;}if(input.time>=36)input.time=0;quote=null;input.eventId=null;play.textContent='Pause';timer=setInterval(()=>{input.time=Math.min(36,input.time+.1);render();if(input.time>=36)stop();},100);};
function action(label,fn){const b=el('button',label);b.onclick=fn;copy.append(b);return b;}
function para(text,cls){copy.append(el('p',text,cls));}
function evidence(m){const d=el('details'),s=el('summary','Inspect the evidence');d.append(s,el('code',JSON.stringify({source:m.source,tracking:m.tracking,events:m.seen,selectedPlayer:focus,position:m.tracking?position(m.s,focus,m.time,m.corrected):null},null,2)));copy.append(d);}
function render(){const m=playEvidence(input);input.time=m.time;range.value=m.time;clock.textContent=`${m.time.toFixed(1)} / 36 s`;tabs.querySelectorAll('button').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.tab===tab)));pitch.update(m.s,matchCenterSnapshot(m.s,m.time,m.corrected),focus,m.corrected);pitchBox.dataset.tracking=m.tracking;
 const svg=pitchBox.querySelector('svg'),old=svg.querySelector('.ps-overlay');old?.remove();const g=document.createElementNS('http://www.w3.org/2000/svg','g');g.classList.add('ps-overlay');g.setAttribute('pointer-events','none');
 const draw=(tag,attrs)=>{const n=document.createElementNS(g.namespaceURI,tag);Object.entries(attrs).forEach(([k,v])=>n.setAttribute(k,v));g.append(n);};
 if(m.tracking){for(const id of new Set([focus,...(m.last?[m.last.from,m.last.interceptor||m.last.to]:[])])){const points=m.trail(id);draw('polyline',{points:points.map(p=>p.join(',')).join(' '),fill:'none',stroke:id===focus?'#ffe773':'#83d8ff','stroke-width':'.65'});const p=position(m.s,id,m.time,m.corrected);draw('circle',{cx:p[0],cy:p[1],r:2.2,fill:'none',stroke:'#fff','stroke-width':'.3'});}}
 if(m.last)draw('line',{x1:m.last.start[0],y1:m.last.start[1],x2:m.last.endPosition[0],y2:m.last.endPosition[1],stroke:'#ff7885','stroke-width':'.65','stroke-dasharray':'1 .8'});svg.append(g);copy.replaceChildren();copy.append(el('small',m.source.toUpperCase()));
 if(tab==='why'){copy.append(el('h3','A sentence you can inspect.'));if(quote){copy.append(el('blockquote',quote.quote));para('The quoted contribution is preserved at its original cutoff. This replay shows the available context; it does not prove every interpretation in the sentence.');para(`Cited sources: ${(quote.ids||[]).join(', ')}`,'ps-note');}const b=action(m.pass,()=>{focus=m.last?.from||focus;render();});b.className='why-sentence';const movementButton=action(m.movement,()=>{focus=m.s.id==='wide'?102:(m.off?.id||focus);render();});movementButton.className='why-sentence ps-fact';para('Gold: selected player’s trail. Blue: players in the latest completed pass. Pink: recorded pass. Select a player to inspect their movement.');evidence(m);}
 if(tab==='off'){copy.append(el('h3','The contribution beyond the ball.'));if(m.off){para(`${m.off.name} · ${m.off.role}`,'ps-fact');para(`${m.off.metres.toFixed(1)} m displacement, with zero recorded ball involvements through this cutoff. That makes this run worth watching; it does not prove it caused the next event.`);action('Spotlight this run',()=>{focus=m.off.id;render();});}else para('No tracked off-ball candidate is available at this cutoff. Restore tracking or move the replay forward.');evidence(m);}
 if(tab==='fans'){copy.append(el('h3','Different loyalties. Identical facts.'));para(`${m.facts.complete}/${m.facts.passes} recorded passes completed · ${m.facts.goals} goals across both teams`,'ps-fact');for(const p of m.perspectives){copy.append(el('h4',p.club));para(p.angle);}para(m.pass);para('Both perspectives use the same event IDs, cutoff, and outcomes. Club preference changes the question, never the evidence.');evidence(m);}
 if(tab==='story'){copy.append(el('h3','Watch an explanation change its mind.'));if(m.s.id!=='wide'){para('This correction experiment uses the wide-run scenario.');action('Open the wide-run case',()=>{input={scenario:'wide',time:16,corrected:false,tracking:true};history=[];render();});}else {para(m.movement,'ps-fact');para('The original tracking shows lateral movement. The corrected source keeps Laurent stationary. Neither source establishes that Moreau caused his movement.');action(m.corrected?'Restore original tracking':'Apply corrected tracking',()=>{stop();history.push({time:m.time,from:m.movement});input.corrected=!m.corrected;history.at(-1).to=playEvidence(input).movement;render();});if(history.length){const list=el('ol',null,'ps-history');for(const h of history){const li=el('li');li.append(el('del',h.from),el('p',h.to),el('small',`Revision at ${h.time.toFixed(1)} s. Event records unchanged.`));list.append(li);}copy.append(list);}}}
 if(tab==='learn'){copy.append(el('h3','One moment. Your way in.'));const choices=el('div',null,'ps-choice');for(const label of ['Show me','Compare it','Let me try','Prove it']){const b=el('button',label);b.setAttribute('aria-pressed',label===learn);b.onclick=()=>{learn=label;guess=null;render();};choices.append(b);}copy.append(choices);
 if(learn==='Show me'){para('A pass moves the ball between players. An off-ball run is movement by someone outside the recorded ball events. Follow the gold trail, then compare it with the pink pass.');para(m.pass);}
 if(learn==='Compare it')para('Think of making room in a crowded hallway: moving to one side can change the space others have. That is an analogy for spacing, not evidence that a particular player caused an opening.');
 if(learn==='Prove it'){para(m.pass,'ps-fact');para('Straight-line speed = distance ÷ elapsed seconds × 3.6. This is an average between synthetic endpoints, not instantaneous ball speed. Displacement is start-to-current distance, not total distance run.');evidence(m);}
 if(learn==='Let me try'){const next=events(m.s).find(e=>e.type==='pass'&&e.t>m.time);if(!next)para('No unrevealed pass remains. Rewind the replay to try an earlier decision.');else{para('Who receives the next recorded pass? Choose before revealing the event. This is a prediction exercise, not a probability model.');const picks=el('div',null,'ps-choice');const ids=[...new Set([next.interceptor||next.to,m.s.focus,8,9])].slice(0,3).sort((a,b)=>a-b);for(const id of ids){const b=el('button',PLAYERS.find(p=>p.id===id).name);b.onclick=()=>{stop();guess=id;input.time=next.end;render();para(`${id===(next.interceptor||next.to)?'Correct.':'Compare your choice with the record.'} ${PLAYERS.find(p=>p.id===next.from).name} → ${PLAYERS.find(p=>p.id===(next.interceptor||next.to)).name}. Source: ${next.id}`,'ps-fact');};picks.append(b);}copy.append(picks);}}}
 if(tab==='missing'){copy.append(el('h3','What can we say without tracking?'));para(m.movement,'ps-fact');action(m.tracking?'Remove player tracking':'Restore player tracking',()=>{stop();input.tracking=!m.tracking;render();});para(m.pass);para('Event endpoints still support this pass line and average speed. Player trails, positions, and off-ball rankings are withheld when tracking is absent. This local experiment does not alter the source dataset or the crew’s saved responses.');evidence(m);}
}
for(const selector of ['.viewing-actions','#centre .extension-heading','#truth .extension-heading']){const host=document.querySelector(selector);if(host){const b=el('button','Inside the play ↗','play-launch');b.onclick=()=>open();host.append(b);}}
window.addEventListener('btr-show-why',e=>open(e.detail));
